//! Cross-language fixtures generated by the actual TypeScript schema/presets.
//! SQLite and payloads are isolated; these tests never access a user's database or Keychain.
use super::*;
use sha2::{Digest, Sha256};

fn fixtures() -> Value {
    serde_json::from_str(include_str!("fixtures/channel-snapshot-contract.json")).unwrap()
}

#[test]
fn channel_contract_fixture_tracks_the_current_typescript_schema() {
    let source = include_bytes!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../src/features/channels/domain/profile.ts"
    ));
    let fingerprint = format!("{:x}", Sha256::digest(source));
    assert_eq!(fixtures()["profileSourceSha256"], fingerprint,
        "TypeScript profile schema changed; regenerate with node scripts/generate-native-channel-contract.mjs and review native parity");
}

#[test]
fn typescript_profiles_with_capabilities_and_display_survive_native_admission_and_sqlite_reload() {
    let fixture = fixtures();
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("contract-jobs.db");
    let mut expected = Vec::new();
    {
        let conn = Connection::open(&path).unwrap();
        ensure_generation_jobs_table(&conn).unwrap();
        for original in fixture["accepted"].as_array().unwrap() {
            // Both unsanitized historical rows and current validated rows use the same contract.
            for scrubbed in [0, 1] {
                let mut snapshot = original.clone();
                let id = format!(
                    "{}-{scrubbed}",
                    snapshot["input"]["jobId"].as_str().unwrap()
                );
                snapshot["input"]["jobId"] = Value::String(id.clone());
                let provider = snapshot["profile"]["id"].as_str().unwrap();
                let model = snapshot["input"]["modelId"].as_str().unwrap();
                let serialized = sanitize_job_poll_descriptor(
                    Some(snapshot.clone()),
                    &id,
                    provider,
                    Some("accepted-once"),
                )
                .unwrap_or_else(|error| panic!("TS fixture {id} must be admitted: {error}"))
                .unwrap();
                conn.execute(
                    "INSERT INTO ai_generation_jobs (job_id, provider_id, media_type, model_id, status, phase, resumable, external_task_id, \
                     poll_descriptor_json, sensitive_fields_scrubbed, submit_attempts, created_at, updated_at) \
                     VALUES (?1, ?2, 'image', ?3, 'recoverable_wait', 'poll', 1, 'accepted-once', ?4, ?5, 1, 1, 1)",
                    params![id, provider, model, serialized, scrubbed],
                ).unwrap();
                expected.push((id, snapshot));
            }
        }
    }
    let conn = Connection::open(path).unwrap();
    ensure_generation_jobs_table(&conn)
        .expect("startup scrubbing must not erase a valid new profile");
    for (id, snapshot) in expected {
        let record = get_generation_job_from_connection(&conn, &id)
            .unwrap()
            .unwrap();
        let dto = dto_from_record(&record);
        assert_eq!(
            dto.poll_descriptor,
            Some(snapshot),
            "lost a TS profile field after reload: {id}"
        );
        assert_eq!(dto.external_task_id.as_deref(), Some("accepted-once"));
        assert_eq!(dto.status, "recoverable_wait");
        assert_eq!(dto.submit_attempts, 1);
    }
}

#[test]
fn native_profile_validation_rejects_the_same_malformed_capabilities_display_and_unknown_fields_as_typescript(
) {
    let fixture = fixtures();
    for mutation in fixture["rejectedProfileMutations"].as_array().unwrap() {
        let mut snapshot = fixture["accepted"][1].clone();
        let path = mutation["path"].as_str().unwrap();
        let (parent, key) = path.rsplit_once('/').unwrap();
        snapshot
            .pointer_mut(parent)
            .unwrap()
            .as_object_mut()
            .unwrap()
            .insert(key.to_string(), mutation["value"].clone());
        assert!(
            sanitize_poll_descriptor(Some(snapshot)).is_err(),
            "native accepted TS-invalid {path}: {}",
            mutation["value"]
        );
    }
}

#[test]
fn new_metadata_does_not_bypass_credential_or_payload_guards() {
    let fixture = fixtures();
    for (path, value) in [
        (
            "/profile/models/0/params/0/default",
            serde_json::json!("Bearer PRIVATE_FIXTURE"),
        ),
        (
            "/profile/models/0/modes/0/params/0/description",
            serde_json::json!("api_key=PRIVATE_FIXTURE"),
        ),
        (
            "/profile/models/0/capabilities",
            serde_json::json!({"apiKey":"PRIVATE_FIXTURE"}),
        ),
        (
            "/profile/models/0/modes/0/endpoint/template",
            serde_json::json!({"image":"data:image/png;base64,AAAA"}),
        ),
        ("/submit", serde_json::json!({"token":"PRIVATE_FIXTURE"})),
        (
            "/input/params",
            serde_json::json!({"authorization":"PRIVATE_FIXTURE"}),
        ),
        (
            "/outputs",
            serde_json::json!([{"kind":"image","url":"https://fixture.example/image?token=PRIVATE_FIXTURE","auth":false}]),
        ),
    ] {
        let mut snapshot = fixture["accepted"][1].clone();
        *snapshot.pointer_mut(path).unwrap() = value;
        assert!(
            sanitize_poll_descriptor(Some(snapshot)).is_err(),
            "sensitive {path} was admitted"
        );
    }
}

#[test]
fn template_snapshot_runtime_fields_keep_their_declared_types() {
    let fixture = fixtures();
    for (path, value) in [
        ("/input/count", serde_json::json!("1")),
        ("/input/count", serde_json::json!(null)),
        ("/input/count", serde_json::json!(true)),
        ("/submit", serde_json::json!([])),
        ("/submit", serde_json::json!(null)),
        ("/assets", serde_json::json!({})),
        ("/assets", serde_json::json!([1])),
        ("/assets", serde_json::json!([{"path":"fixture"}])),
    ] {
        let mut snapshot = fixture["accepted"][1].clone();
        *snapshot.pointer_mut(path).unwrap() = value;
        assert!(
            sanitize_poll_descriptor(Some(snapshot)).is_err(),
            "invalid runtime field {path} was admitted"
        );
    }
    for (parent, key) in [("/input", "count"), ("", "submit")] {
        let mut snapshot = fixture["accepted"][1].clone();
        snapshot
            .pointer_mut(parent)
            .unwrap()
            .as_object_mut()
            .unwrap()
            .remove(key);
        assert!(
            sanitize_poll_descriptor(Some(snapshot)).is_err(),
            "missing runtime field {key} was admitted"
        );
    }
}
